// Gera um atraso aleatório entre 20s e 80s para CADA item
const MIN_S = 10;      // 20 segundos
const MAX_S = 80;      // 1 min 20s

for (const item of items) {
  const s = Math.floor(MIN_S + Math.random() * (MAX_S - MIN_S + 1));
  item.json.delaySeconds = s;        // ex.: 37
  item.json.delayMs = s * 1000;      // ex.: 37000
  item.json.delayHuman = `${s}s`;    // útil para logs/debug
}

return items;
